mapper.select:
SELECT
A.BOOKSET_ID bookSetId,/**账套代码**/
DECODE(A.BASE_SUBJECT_NATURE,'QTYSK_BJ','其他应收款-本金','QTYSK_LX','其他应收款-利息') AS receivablesType,
A.FINPROD_ID AS bdFinprodId, /**标的资产代码**/
B.FINPROD_NAME   AS bdFinprodName ,/**标的资产名称**/
A.prinamt,
A.intamt,
CASE WHEN A.BASE_SUBJECT_NATURE = 'QTYSK_LX' THEN DATE_FORMAT(D.VDATE,'%Y-%m-%d') ELSE NULL END vdate, /**计息开始日**/
CASE WHEN A.BASE_SUBJECT_NATURE = 'QTYSK_LX' THEN DATE_FORMAT(D.MDATE,'%Y-%m-%d') ELSE NULL END mdate,  /**计息截止日**/
CASE WHEN A.BASE_SUBJECT_NATURE = 'QTYSK_BJ' THEN DATE_FORMAT(D.MDATE,'%Y-%m-%d') ELSE NULL END tradeDate,/**还本日**/
CALC.BASIS basis,/**计息基础**/
CALC.CALC_TYPE calcType,/**利率类型**/
CALC.YIELD yield /**最新利率(%)**/
FROM (
SELECT
A.BOOKSET_ID,
A.BUSI_ID AS FINPROD_ID,
B.BUSI_DETAIL_TYPE AS FINPROD_TYPE,
A.BRANCH,
A.BASE_SUBJECT_NATURE,
SUM(CASE WHEN A.BASE_SUBJECT_NATURE ='QTYSK_BJ' THEN A.O_AMT_HAPPEN_DATE ELSE 0 END) AS PRINAMT,
SUM(CASE WHEN A.BASE_SUBJECT_NATURE ='QTYSK_LX' THEN A.O_AMT_HAPPEN_DATE ELSE 0 END) AS INTAMT
FROM (
SELECT A.* FROM (
SELECT
@rownum := @rownum + 1 rownum,
A.BOOKSET_ID,
A.BUSI_ID,
A.BRANCH,
A.BOOK_DATE,
A.BOK_DETAIL_ID,
A.BASE_SUBJECT_NATURE,
A.O_AMT_HAPPEN_DATE,
IF
(
(
@BOOKSET_ID = A.BOOKSET_ID
AND @BOK_DETAIL_ID = A.BOK_DETAIL_ID
AND @BASE_SUBJECT_NATURE = A.BASE_SUBJECT_NATURE
AND @SUBJECT_NO = A.SUBJECT_NO
AND @BRANCH = A.BRANCH
),
@rank := @rank + 1,
@rank := 1
) AS newResult,
@BOOKSET_ID := A.BOOKSET_ID,
@BOK_DETAIL_ID := A.BOK_DETAIL_ID,
@BASE_SUBJECT_NATURE := A.BASE_SUBJECT_NATURE,
@BRANCH := A.BRANCH,
@SUBJECT_NO := A.SUBJECT_NO
FROM
( SELECT * FROM BOK_BOOKDETAIL_CURRENT ORDER BY BOOKSET_ID,BOK_DETAIL_ID, BASE_SUBJECT_NATURE, BRANCH, SUBJECT_NO, BOOK_ORDER desc ) A,
(
SELECT
@rownum := 0,
@BOOKSET_ID := NULL,
@BOK_DETAIL_ID := NULL,
@BASE_SUBJECT_NATURE := NULL,
@SUBJECT_NO := NULL,
@BRANCH := NULL,
@rank := 0
) B
WHERE A.BASE_SUBJECT_NATURE IN ('QTYSK_BJ','QTYSK_LX')
AND A.BOOK_DATE <= to_date(#{bookDate},'%Y-%m-%d')    /**账务日期**/

	AND A.BASE_SUBJECT_NATURE = #{receivablesType}


	AND A.BOOKSET_ID = #{bookSetId}


	AND A.BUSI_ID in

		#{bdFinprodId}


) A WHERE A.newResult=1
AND A.O_AMT_HAPPEN_DATE != 0
) A,BOK_DETAIL_ID B
WHERE A.BOOKSET_ID = B.BOOKSET_ID
AND A.BOK_DETAIL_ID = B.BOK_DETAIL_ID

	AND A.BASE_SUBJECT_NATURE = #{receivablesType}


	AND A.BOOKSET_ID = #{bookSetId}


	AND A.BUSI_ID in

		#{bdFinprodId}


GROUP BY A.BOOKSET_ID, A.BUSI_ID,B.BUSI_DETAIL_TYPE,A.BRANCH, A.BASE_SUBJECT_NATURE
) A
LEFT JOIN (
SELECT
R.FINPROD_ID,R.FINPROD_TYPE,
DECODE(R.CALC_TYPE,'01','固定利率','02','浮动利率') AS CALC_TYPE,
ROUND(R.YIELD*100,4) YIELD,R.BASIS FROM FIN_CASH_CALC_RULE R,(
SELECT G.CASH_ID,F.FINPROD_ID,F.FINPROD_TYPE,MAX(F.EFF_DATE) EFF_DATE
FROM FIN_CASH_CALC_RULE F,FIN_CASH_INFO G
WHERE F.FINPROD_ID = G.FINPROD_ID AND F.FINPROD_TYPE = G.FINPROD_TYPE
AND G.CASH_TYPE_1 ='02'
GROUP BY G.CASH_ID,F.FINPROD_ID,F.FINPROD_TYPE
) H
WHERE R.CASH_ID = H.CASH_ID AND R.FINPROD_ID = H.FINPROD_ID
AND R.FINPROD_TYPE = H.FINPROD_TYPE
AND R.EFF_DATE = H.EFF_DATE
) CALC ON A.FINPROD_ID = CALC.FINPROD_ID AND A.FINPROD_TYPE = CALC.FINPROD_TYPE
LEFT JOIN FIN_PRODUCT B ON A.FINPROD_ID = B.FINPROD_ID AND A.FINPROD_TYPE = B.FINPROD_TYPE
LEFT JOIN FIN_TRADE_PRODUCT D ON A.FINPROD_ID = D.FINPROD_ID AND A.FINPROD_TYPE = D.FINPROD_TYPE AND A.BRANCH = D.BRANCH
WHERE A.BASE_SUBJECT_NATURE IN ('QTYSK_BJ','QTYSK_LX')

	AND D.MDATE >= to_date(#{vdate},'%Y-%m-%d')


	AND D.MDATE <=to_date(#{mdate},'%Y-%m-%d')

ORDER BY  A.BOOKSET_ID,A.FINPROD_TYPE,A.FINPROD_ID,A.BASE_SUBJECT_NATURE
